// Import of required libraries
import { test, expect, SkyrampClient, getBaseUrl, getValue, getResponseValue } from '@skyramp/skyramp';
import { createCollection, updateCollection, getPublicCollections, deleteCollection } from './skyrampUtils';

// URL for test requests
const URL_localhost = getBaseUrl("SKYRAMP_TEST_BASE_URL", "http://localhost:3000");

test('testIntegration', async () => {
    test.setTimeout(60000);

    // Invocation of Skyramp Client
    const client = new SkyrampClient();
    // Definition of authentication header
    const headers: Record<string, string> = {};
    if (process.env.SKYRAMP_TEST_TOKEN && process.env.SKYRAMP_TEST_TOKEN != "") {
        headers["Authorization"] = "Bearer " + process.env.SKYRAMP_TEST_TOKEN;
    }

    const collectionsPostResponse = await createCollection(
        client,
        headers,
        "Skyramp Public Collection",
        "Skyramp public collection"
    );

    expect(getResponseValue(collectionsPostResponse, "response.name"), 'name').toBe("Skyramp Public Collection");
    expect(getResponseValue(collectionsPostResponse, "response.description"), 'description').toBe("Skyramp public collection");
    expect(getResponseValue(collectionsPostResponse, "response.isPublic"), 'isPublic defaults to false on create').toBe(false);
    expect(getResponseValue(collectionsPostResponse, "response.id"), 'id').toBeGreaterThan(0);
    expect(getResponseValue(collectionsPostResponse, "response.createdAt"), 'createdAt').toMatch(/^\d{4}-\d{2}-\d{2}T/);

    const collectionsCollectionsPutResponse = await updateCollection(
        client,
        headers,
        getResponseValue(collectionsPostResponse, "response.id"),
        "Skyramp Public Collection",
        "Skyramp public collection",
        true
    );

    expect(getResponseValue(collectionsCollectionsPutResponse, "response.id"), 'id').toBe(getResponseValue(collectionsPostResponse, "response.id"));
    expect(getResponseValue(collectionsCollectionsPutResponse, "response.isPublic"), 'isPublic').toBe(true);
    expect(getResponseValue(collectionsCollectionsPutResponse, "response.name"), 'name').toBe("Skyramp Public Collection");
    expect(getResponseValue(collectionsCollectionsPutResponse, "response.description"), 'description').toBe("Skyramp public collection");

    const collectionsPost1Response = await createCollection(
        client,
        headers,
        "Skyramp Private Collection",
        "Skyramp private collection"
    );

    expect(collectionsPost1Response.statusCode, 'status code').toBe(200);
    expect(getResponseValue(collectionsPost1Response, "response.name"), 'name').toBe("Skyramp Private Collection");
    expect(getResponseValue(collectionsPost1Response, "response.description"), 'description').toBe("Skyramp private collection");
    expect(getResponseValue(collectionsPost1Response, "response.isPublic"), 'isPublic defaults to false on create').toBe(false);
    expect(getResponseValue(collectionsPost1Response, "response.id"), 'id').toBeGreaterThan(0);

    const publicGetResponse = await getPublicCollections(client, headers);

    expect(getValue(publicGetResponse, "response").length, 'only the public collection is listed').toBe(1);
    expect(getResponseValue(publicGetResponse, "response.0.id"), 'id').toBe(getResponseValue(collectionsPostResponse, "response.id"));
    expect(getResponseValue(publicGetResponse, "response.0.name"), 'name').toBe("Skyramp Public Collection");
    expect(getResponseValue(publicGetResponse, "response.0.description"), 'description').toBe("Skyramp public collection");
    expect(getResponseValue(publicGetResponse, "response.0.isPublic"), 'isPublic').toBe(true);
    expect(getResponseValue(publicGetResponse, "response.1"), 'the private collection is not listed').toBeNull();

    const collectionsCollectionsDeleteResponse = await deleteCollection(
        client,
        headers,
        getResponseValue(collectionsPostResponse, "response.id")
    );

    expect(getResponseValue(collectionsCollectionsDeleteResponse, "response.id"), 'id').toBe(getResponseValue(collectionsPostResponse, "response.id"));

    const collectionsCollectionsDelete1Response = await deleteCollection(
        client,
        headers,
        getResponseValue(collectionsPost1Response, "response.id")
    );

    expect(collectionsCollectionsDelete1Response.statusCode, 'status code').toBe(200);
    expect(getResponseValue(collectionsCollectionsDelete1Response, "response.id"), 'id').toBe(getResponseValue(collectionsPost1Response, "response.id"));
});
